-- READ-ONLY preview: what cleanup_test_shipments.sql would delete (same filter). One result set per statement.
-- (D1 limits compound SELECTs, hence separate statements.)
SELECT 'shipments' AS tabel, COUNT(*) AS baris, group_concat(awb) AS detail FROM shipments WHERE awb IN (SELECT awb FROM shipments WHERE awb IN ('TEST0013','TEST0012','TEST0011','TEST0010','TEST0009','TEST0008','__NONE__0005') OR awb LIKE 'TEST%' ESCAPE '\' OR awb LIKE '\_\_NONE\_\_%' ESCAPE '\');
