SELECT 'recycle_bin' AS tabel, COUNT(*) AS baris, NULL AS detail FROM recycle_bin WHERE entity_type='shipment' AND entity_id IN (SELECT awb FROM shipments WHERE awb IN ('TEST0013','TEST0012','TEST0011','TEST0010','TEST0009','TEST0008','__NONE__0005') OR awb LIKE 'TEST%' ESCAPE '\' OR awb LIKE '\_\_NONE\_\_%' ESCAPE '\');
SELECT 'files' AS tabel, COUNT(*) AS baris, group_concat(object_key,' | ') AS detail FROM files WHERE (entity_type IN ('shipment_photo','shipment_surat_jalan','pod_barang','pod_surat_jalan') AND entity_id IN (SELECT awb FROM shipments WHERE awb IN ('TEST0013','TEST0012','TEST0011','TEST0010','TEST0009','TEST0008','__NONE__0005') OR awb LIKE 'TEST%' ESCAPE '\' OR awb LIKE '\_\_NONE\_\_%' ESCAPE '\')) OR (entity_type='timeline_photo' AND entity_id IN (SELECT id FROM shipment_timeline_events WHERE awb IN (SELECT awb FROM shipments WHERE awb IN ('TEST0013','TEST0012','TEST0011','TEST0010','TEST0009','TEST0008','__NONE__0005') OR awb LIKE 'TEST%' ESCAPE '\' OR awb LIKE '\_\_NONE\_\_%' ESCAPE '\')));
